-- Literal inputs to the actual jobs_detail model (not a copied classifier).
with cases as (
    select j from unnest(json_query_array(json '''[
      {"id":"intellipro","description":"This is a hybrid role: alternating weeks onsite and remote. No 100% remote."},
      {"id":"gdit","description":"Workplace: Hybrid. This role is hybrid.","wfh":true},
      {"id":"walmart","description":"This role requires onsite attendance and is not eligible for remote work.","wfh":true},
      {"id":"fusionauth","description":"This role is remote or hybrid."},
      {"id":"technical_hybrid","title":"Hybrid Cloud Engineer","description":"Build hybrid cloud infrastructure with Microsoft Office tools."},
      {"id":"technical_remote","title":"Remote Sensing Analyst","description":"Manage remote systems and remote access."},
      {"id":"policy","description":"We offer flexible working policies. Our company supports remote employees and hybrid teams."},
      {"id":"geo","description":"This role is fully remote within the United States. Must reside in California."},
      {"id":"travel","description":"This is a fully remote role with occasional travel to client sites."},
      {"id":"annual","description":"This role is fully remote with required onsite attendance at an annual retreat."},
      {"id":"onboarding","description":"This role is fully remote with onsite onboarding for the first two days."},
      {"id":"tag_conflict","description":"#LI-Remote #LI-Hybrid"},
      {"id":"tag_only","description":"#LI-Remote"},
      {"id":"tag_overridden","description":"This role is onsite. #LI-Remote"},
      {"id":"tag_same_sentence","description":"This role is onsite #LI-Remote #LI-Hybrid"},
      {"id":"null"},
      {"id":"false_flag","wfh":false},
      {"id":"true_flag","wfh":true},
      {"id":"title_remote","title":"Data Engineer (Remote)"},
      {"id":"title_office","title":"Data Engineer - On-site"},
      {"id":"title_hybrid","title":"Data Engineer (Hybrid)"},
      {"id":"title_override","title":"Data Engineer (Remote)","description":"This role requires onsite attendance."},
      {"id":"negative","description":"Not remote."},
      {"id":"experience","description":"No remote work experience required; fully remote role."},
      {"id":"strong_conflict","description":"This role is fully remote. This position is onsite."},
      {"id":"temporal","description":"This role is initially onsite and eventually remote."},
      {"id":"conditional","description":"This role is remote subject to approval."},
      {"id":"unicode","description":"This role is fully\\nremote — within the U.S. only."},
      {"id":"schedule","description":"Work onsite 3 days per week and work from home 2 days per week."},
      {"id":"alternating","description":"Alternating weeks: one week onsite and one week remote."},
      {"id":"extension","extensions":["Remote"]},
      {"id":"not_exact","extensions":["Remote systems experience"]},
      {"id":"extension_conflict","extensions":["Remote","Hybrid"]},
      {"id":"li_metadata","metadata":"Full-time · Hybrid"},
      {"id":"highlight","highlights":[{"title":"Responsibilities","item":"This role is hybrid."}]},
      {"id":"benefits","highlights":[{"title":"Benefits","item":"You can work from home."}]},
      {"id":"microsoft","description":"Must have Microsoft Office experience."},
      {"id":"negative_title","title":"Engineer (Not Remote)"},
      {"id":"locality","title":"Engineer - Remote","description":"For candidates based in Austin, this role follows a hybrid work model."},
      {"id":"negated_options","description":"This is an on-site opportunity. It is not a remote or hybrid position."},
      {"id":"location_options","title":"Senior Data Engineer (REMOTE OR MA BASED)","description":"Join our team in our Worcester MA office, or via a remote work arrangement."},
      {"id":"company_remote","description":"We are a fully remote company."},
      {"id":"company_hybrid","description":"Our company offers a hybrid work model. All employees can work from home."},
      {"id":"technical_fully_remote","description":"Build fully remote systems for customers."},
      {"id":"not_hybrid","description":"Not hybrid, this is a remote position."},
      {"id":"remote_first_recurring","description":"This role is remote with required onsite attendance every Monday."},
      {"id":"two_day_retreat","description":"This role is remote with 2 days onsite at an annual retreat."},
      {"id":"title_labels_conflict","title":"Engineer (Remote) (Hybrid)"},
      {"id":"office_not_required","description":"This role does not require onsite attendance."},
      {"id":"office_negated_role","description":"This is not an onsite role."},
      {"id":"remote_office_not_required","description":"This role is fully remote and does not require onsite attendance."},
      {"id":"temporal_remote_first","description":"This role is remote for the first month and onsite thereafter."},
      {"id":"temporal_office_first","description":"This role is onsite for the first month, then fully remote."},
      {"id":"hybrid_partial_office","description":"This is a hybrid role. You will work onsite 3 days per week."},
      {"id":"quantified_split_mix","description":"You will work onsite 3 days per week. You can work from home 2 days per week."},
      {"id":"technical_powertrain","title":"Hybrid Powertrain Engineer"},
      {"id":"technical_role_sensing","description":"This role is remote sensing focused and requires satellite imagery experience."},
      {"id":"hybrid_full_office_conflict","description":"This is a hybrid role. This role is fully onsite."},
      {"id":"remote_partial_office_conflict","description":"This role is fully remote. You will work onsite 3 days per week."},
      {"id":"unquantified_split_conflict","description":"This role is onsite. You can work from home."},
      {"id":"impossible_weekly_mix","description":"You will work onsite 4 days per week. You can work from home 4 days per week."},
      {"id":"same_sentence_hybrid_conflict","description":"This is a hybrid role and this is an onsite role."},
      {"id":"full_remote_weekly_conflict","description":"This role is fully remote and you will work onsite 3 days per week."},
      {"id":"same_sentence_impossible_mix","description":"You will work onsite 4 days per week and you can work from home 4 days per week."},
      {"id":"unrelated_remote_people","description":"You will work onsite 3 days per week and collaborate with remote colleagues."},
      {"id":"office_not_require_you","description":"This role does not require you to work onsite."},
      {"id":"office_not_require_candidates","description":"This role does not require candidates to be in-office."},
      {"id":"office_not_require_working","description":"This position does not mandate working on-site."},
      {"id":"office_passive_not_required","description":"Onsite attendance is not required for this role."},
      {"id":"office_passive_not_mandatory","description":"Working in-office will not be mandatory for this role."},
      {"id":"office_not_required_to_work","description":"You are not required to work onsite."},
      {"id":"title_prohibited_remote","title":"Engineer (Remote)","description":"Remote work is not available for this role."},
      {"id":"title_prohibited_remote_allowed","title":"Engineer (Remote)","description":"Working from home is not permitted for this position."},
      {"id":"wfh_prohibited_remote","description":"Remote work is not available for this role.","wfh":true},
      {"id":"metadata_prohibited_remote","extensions":["Remote","Remote work is not available"]},
      {"id":"metadata_negated_office","extensions":["Onsite attendance is not required"]},
      {"id":"negative_office_positive_remote","description":"Onsite attendance is not required for this role. This role is fully remote."},
      {"id":"negative_office_positive_office","description":"Onsite attendance is not required for other roles. This role is onsite."},
      {"id":"remote_experience_not_required","description":"Remote work experience is not required. This role is fully remote."},
      {"id":"remote_unavailable_positive_office","title":"Engineer (Remote)","description":"Remote work is not available for this role. This role is onsite."},
      {"id":"onboarding_remote_then_office","description":"This role is remote for the first month of onboarding, then onsite."},
      {"id":"onboarding_office_then_remote_month","description":"This role is onsite for the first month of onboarding, then fully remote."},
      {"id":"onboarding_short_remote_then_office","description":"This role is remote for the first two days of onboarding, then onsite."},
      {"id":"onboarding_short_office_then_remote","description":"This role is onsite for the first two days of onboarding, then fully remote."},
      {"id":"quantified_imperative_impossible","description":"Work onsite 4 days per week and work from home 4 days per week."},
      {"id":"quantified_imperative_compatible","description":"Work onsite 3 days per week and work from home 2 days per week."},
      {"id":"quantified_imperative_split_compatible","description":"Work onsite 3 days per week. Work from home 2 days per week."},
      {"id":"remote_not_required_quantified","description":"You are not required to work from home 2 days per week."},
      {"id":"remote_not_required_quantified_office","description":"You are not required to work from home 2 days per week. This role is onsite."},
      {"id":"remote_not_necessary_quantified","description":"It is not necessary to work from home 2 days per week."},
      {"id":"remote_not_necessary_quantified_office","description":"It is not necessary to work from home 2 days per week. This role is onsite."},
      {"id":"remote_passive_not_required_quantified","description":"Working from home 2 days per week is not required."},
      {"id":"remote_passive_not_required_quantified_office","description":"Working from home 2 days per week is not required. This role is onsite."},
      {"id":"wfh_passive_neutral","description":"WFH is not required for this role."},
      {"id":"wfh_passive_neutral_office","description":"WFH is not required for this role. This role is onsite."},
      {"id":"remote_obligation_active_neutral","description":"This role does not require you to work from home 2 days per week."},
      {"id":"remote_obligation_active_neutral_office","description":"This role does not require you to work from home 2 days per week. This role is onsite."},
      {"id":"remote_obligation_neutral_positive","description":"You are not required to work from home 2 days per week. This role is fully remote."},
      {"id":"office_obligation_neutral_quantified","description":"It is not necessary to work onsite 3 days per week."},
      {"id":"office_obligation_neutral_no_mix","description":"You are not required to work onsite 3 days per week. Work from home 2 days per week."},
      {"id":"remote_permission_quantified_title","title":"Engineer (Remote)","description":"Work from home 2 days per week is not permitted for this role."},
      {"id":"remote_permission_unavailable_title","title":"Engineer (Remote)","description":"Remote work is not available for this role."},
      {"id":"remote_neutral_metadata","extensions":["Remote work is not required"],"wfh":true},
      {"id":"remote_passive_work_neutral","description":"Work from home 2 days per week is not necessary."},
      {"id":"remote_passive_work_neutral_office","description":"Work from home 2 days per week is not necessary. This role is onsite."}
    ]''')) j
)
select
    json_value(j, '$.id') as job_id,
    json_value(j, '$.id') as platform_job_id,
    timestamp '2026-10-01 00:00:00+00' as created_at_utc,
    datetime '2026-09-30 18:00:00' as created_at_mst,
    coalesce(json_value(j, '$.title'), 'Data Engineer') as job_title,
    'Fixture' as company_name,
    'denver' as search_location,
    'Data Engineer' as search_term,
    cast(null as string) as job_location,
    'Fixture' as job_platform,
    date '2026-10-01' as posted_date_parsed,
    'Full-time' as schedule_type,
    cast(null as float64) as low_annual_pay_range,
    cast(null as float64) as high_annual_pay_range,
    json_value(j, '$.description') as job_description,
    if(json_value(j, '$.metadata') is null, 'Serpapi', 'LinkedIn') as data_source,
    cast(null as string) as degree_requirement,
    cast(null as string) as source_link,
    array(select json_value(e) from unnest(json_query_array(j, '$.extensions')) e) as work_setting_extensions,
    array(select as struct json_value(h, '$.title') as title, json_value(h, '$.item') as item
          from unnest(json_query_array(j, '$.highlights')) h) as work_setting_highlights,
    safe_cast(json_value(j, '$.wfh') as bool) as work_from_home,
    json_value(j, '$.metadata') as work_setting_source_metadata
from cases
